const body = $json.body ?? $json;
const platforms = ['whatsapp','facebook','instagram','linkedin','x','telegram','tiktok','youtube','gmail','outlook','3cx'];
if (!platforms.includes(String(body.platform || '').toLowerCase())) return [{json:{success:false,status:'unsupported',error:'unsupported_platform',platform:body.platform ?? null}}];
if (!body.action) return [{json:{success:false,status:'rejected',error:'action_required',platform:body.platform}}];
return [{json:{platform:String(body.platform).toLowerCase(),action:String(body.action),connection_id:body.connection_id ?? null,client_id:body.client_id ?? null,target_type:body.target_type ?? null,target_id:body.target_id ?? null,idempotency_key:body.idempotency_key ?? ('n8n-' + $execution.id),payload:body.payload ?? {}}}];
